<section class="page-heading"><div><p class="page-kicker">Logistique</p><h2>Demande de transfert</h2></div></section><section class="form-panel"><form method="post" action="<?=e(base_url('transfers'))?>" class="enterprise-form"><?=csrf_field()?><div class="form-grid"><label><span>Type</span><select name="transfer_type"><option value="inter_site">BTR inter-site</option><option value="internal">BTI interne</option></select></label><label><span>Site émetteur</span><select name="source_site_id" required><?php foreach($sites as$s):?><option value="<?=e($s['id'])?>"><?=e($s['code'].' — '.$s['name'])?></option><?php endforeach;?></select></label><label><span>Site destinataire</span><select name="destination_site_id" required><?php foreach($sites as$s):?><option value="<?=e($s['id'])?>"><?=e($s['code'].' — '.$s['name'])?></option><?php endforeach;?></select></label><label><span>Lot disponible</span><select name="finished_stock_id" required><?php foreach($stocks as$s):?><option value="<?=e($s['id'])?>"><?=e($s['site_code'].' — '.$s['product_name'].' — '.$s['format_name'].' — disponible '.($s['quantity_bags']-$s['reserved_bags']))?></option><?php endforeach;?></select></label><label><span>Nombre de sacs</span><input type="number" min="1" name="quantity_bags" required></label><label><span>Notes</span><textarea name="notes"></textarea></label></div><button class="btn-primary">Créer la demande</button></form></section>
